<script setup lang="ts">
import { ref, computed, onMounted } from 'vue'
import { api } from './api'
import { renderMarkdown } from './htmlArtifacts'
import { Search, Plus, Check, Upload, ArrowUpRight, X, Sparkles, Blocks, SlidersHorizontal, Plug, Activity, RefreshCw, Download, Play, Trash2, FileCode2 } from 'lucide-vue-next'
const props = defineProps<{courseId:number;threadId:number|null}>()
const emit = defineEmits<{saved:[];chat:[string]}>()
type Skill = {id:string;name:string;description:string;category:string;icon:string;builtin:boolean;source:string;version:string;instructions?:string;resources?:Record<string,string>;resource_names:string[];source_url?:string;requirements?:string;license?:string}
type App = {id:string;name:string;icon:string;description:string;prompt:string;starter:string}
type Config = {app_id:string;template:string;skill_ids:string[];mcp_refs:string[];use_knowledge:boolean}
type Server = {id:number;name:string;url:string;connected:boolean;has_token:boolean;tools:{name:string;description:string;inputSchema:unknown}[];error:string}
type Trace = {id:number;status:string;model:string;started_at:string;events:{event_type:string;payload:any;sequence:number}[];error:string}
const section = ref('skills'), search = ref(''), category = ref('全部'), skills = ref<Skill[]>([]), apps = ref<App[]>([])
const config = ref<Config>({app_id:'general',template:'',skill_ids:[],mcp_refs:[],use_knowledge:false})
const platformServers = ref<Server[]>([])
const servers = ref<Server[]>([]), traces = ref<Trace[]>([]), detail = ref<Skill|null>(null), manager = ref(false)
const busy = ref(false), notice = ref(''), provider = ref(''), model = ref(''), selectedTrace = ref<Trace|null>(null)
const serverName = ref(''), serverUrl = ref(''), tokenEnv = ref(''), testing = ref<number|null>(null)
const testTool = ref(''), testArgs = ref('{}'), testOutput = ref('')
const categories = computed(()=>['全部',...new Set(skills.value.map(s=>s.category))])
const filtered = computed(()=>skills.value.filter(s=>(category.value==='全部'||s.category===category.value)&&`${s.name} ${s.description} ${s.source}`.toLowerCase().includes(search.value.toLowerCase())))
const nav = [{id:'apps',name:'AI 应用',icon:Sparkles},{id:'skills',name:'技能广场',icon:Blocks},{id:'prompts',name:'助手配置',icon:SlidersHorizontal},{id:'mcp',name:'工具与 MCP',icon:Plug},{id:'traces',name:'运行追踪',icon:Activity}]
async function attempt(fn:()=>Promise<void>){busy.value=true;notice.value='';try{await fn()}catch(e){notice.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function load(){const c=await api<{apps:App[];skills:Skill[];can_manage_mcp:boolean;provider:string;model:string}>('agent/catalog/');apps.value=c.apps;skills.value=c.skills;manager.value=c.can_manage_mcp;provider.value=c.provider;model.value=c.model;config.value=await api<Config>(`courses/${props.courseId}/assistant/`);platformServers.value=await api<Server[]>('agent/platform-tools/');if(manager.value)servers.value=await api<Server[]>('agent/mcp/')}
async function save(){config.value=await api<Config>(`courses/${props.courseId}/assistant/`,'PUT',config.value);emit('saved')}
async function toggle(skill:Skill){await attempt(async()=>{const before=[...config.value.skill_ids];config.value.skill_ids=before.includes(skill.id)?before.filter(id=>id!==skill.id):[...before,skill.id];try{await save();notice.value=config.value.skill_ids.includes(skill.id)?`已将「${skill.name}」添加到本课程助手`:'已从助手移除'}catch(e){config.value.skill_ids=before;throw e}})}
async function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;await attempt(async()=>{const form=new FormData();form.append('file',file);await api('agent/skills/upload/','POST',form);await load();category.value='我的上传';notice.value='技能已上传，可查看内容并添加到助手'});input.value=''}
async function openSkill(skill:Skill){await attempt(async()=>{detail.value=await api<Skill>(`agent/skills/${skill.id}/`)})}
async function selectApp(app:App){await attempt(async()=>{config.value.app_id=app.id;await save();emit('chat',app.starter)})}
async function addServer(demo=false){await attempt(async()=>{await api('agent/mcp/','POST',{name:demo?'campus-tools':serverName.value,url:demo?'http://campus-tools:8100/mcp':serverUrl.value,token_env:demo?'MCP_CAMPUS_TOKEN':tokenEnv.value});servers.value=await api<Server[]>('agent/mcp/');serverName.value='';serverUrl.value='';tokenEnv.value='';notice.value='服务器已登记，点击连接以握手并发现工具'})}
async function connect(s:Server){await attempt(async()=>{await api(`agent/mcp/${s.id}/`,'POST',{action:s.connected?'disconnect':'connect'});servers.value=await api<Server[]>('agent/mcp/')})}
async function bindTool(s:Server,name:string){await attempt(async()=>{const ref=`${name}@${s.name}`,before=[...config.value.mcp_refs];config.value.mcp_refs=before.includes(ref)?before.filter(r=>r!==ref):[...before,ref];try{await save()}catch(e){config.value.mcp_refs=before;throw e}})}
async function loadTraces(){await attempt(async()=>{if(!props.threadId){traces.value=[];return}traces.value=await api<Trace[]>(`agent/threads/${props.threadId}/traces/`);selectedTrace.value=traces.value[0]||null})}
async function switchSection(id:string){section.value=id;if(id==='traces')await loadTraces()}
function exportTrace(){const blob=new Blob([JSON.stringify(traces.value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`campusclaw-trace-${props.threadId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function eventLabel(type:string){return ({context:'01 · 上下文与绑定',retrieval:'02 · 知识库检索',llm_request:'模型请求',llm_response:'模型返回',tool_call:'工具调用',tool_result:'工具结果',error:'失败原因',message_start:'开始',message_end:'完成',artifact:'生成文件',citation:'资料引用'} as Record<string,string>)[type]||type}
function prepareTest(server:Server,name:string){testing.value=server.id;testTool.value=`mcp_${server.id}_${name}`;testOutput.value='';const samples:Record<string,unknown>={browser_open:{url:'https://example.com'},python_execute:{code:'print(sum(range(1,101)))'},shell_execute:{command:"node -e 'console.log(6*7)'"},formula_hint:{topic:'复合函数求导'},unit_convert:{value:2,from_unit:'km',to_unit:'m'},learning_checklist:{subject:'MCP'}};testArgs.value=JSON.stringify(samples[name]||{},null,2)}
async function tryTool(){if(!props.threadId){notice.value='请先在对话页新建一个对话，再测试工具';return}await attempt(async()=>{const args=JSON.parse(testArgs.value);testOutput.value=JSON.stringify(await api(`agent/threads/${props.threadId}/tool-test/`,'POST',{name:testTool.value,arguments:args}),null,2)})}
onMounted(()=>attempt(load))
</script>

<template>
<div class="studio">
  <div class="studio-top"><div><span class="studio-eyebrow">CAMPUSCLAW / WORKSPACE</span><h2>让助手，多一项拿手好戏<span>✦</span></h2><p>挑选技能，连接工具，打造属于这门课的 AI 工作空间。</p></div><div class="studio-count"><strong>{{config.skill_ids.length.toString().padStart(2,'0')}}</strong><span>技能已添加</span></div></div>
  <nav class="studio-nav"><button v-for="item in nav" :key="item.id" :class="{active:section===item.id}" @click="switchSection(item.id)"><component :is="item.icon" :size="16"/>{{item.name}}</button></nav>
  <div v-if="notice" class="studio-notice" role="status">{{notice}}<button @click="notice=''" aria-label="关闭提示"><X :size="14"/></button></div>
  <div v-if="provider==='mock'" class="studio-demo">当前为演示模型：工具可以真实测试；对话自动选择技能与工具需配置真实模型。</div>
  <section v-if="section==='skills'">
    <div class="studio-section-head"><div><h3>技能广场 <span>{{skills.length}}</span></h3><p>精选开源技能与课程实用技能，按需读取、执行脚本。</p></div><label class="secondary studio-upload"><Upload :size="15"/>上传技能<input type="file" accept=".md,.zip" @change="upload" :disabled="busy"></label></div>
    <div class="studio-filters"><div class="studio-search"><Search :size="16"/><input v-model="search" placeholder="搜索技能、用途或来源" aria-label="搜索技能"></div><div class="studio-categories"><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div></div>
    <div class="skill-grid"><article v-for="s in filtered" :key="s.id" class="skill-card" :class="{installed:config.skill_ids.includes(s.id)}"><div class="skill-card-top"><span class="skill-symbol">{{s.icon}}</span><span class="skill-category">{{s.category}}</span></div><button class="skill-title" @click="openSkill(s)">{{s.name}}<ArrowUpRight :size="15"/></button><p>{{s.description}}</p><div class="skill-source">{{s.source}}</div><div class="skill-card-foot"><button class="skill-detail" @click="openSkill(s)">查看技能</button><button class="skill-add" :class="{added:config.skill_ids.includes(s.id)}" :disabled="busy" @click="toggle(s)"><Check v-if="config.skill_ids.includes(s.id)" :size="14"/><Plus v-else :size="14"/>{{config.skill_ids.includes(s.id)?'已添加':'添加到助手'}}</button></div></article></div>
    <div v-if="!filtered.length" class="studio-empty">没有找到匹配的技能，试试其他关键词或上传自己的技能。</div>
    <div class="studio-footnote">支持 SKILL.md 与 ZIP 技能包 · Python / JavaScript / Shell 隔离执行 · 参考文件按需加载</div>
  </section>
  <section v-if="section==='apps'"><div class="studio-section-head"><div><h3>为不同任务，切换一种思路</h3><p>应用有独立的角色提示词，技能与知识库配置继续生效。</p></div></div><div class="app-grid"><button v-for="app in apps" :key="app.id" class="studio-app" @click="selectApp(app)"><span class="app-symbol">{{app.icon}}</span><span v-if="config.app_id===app.id" class="app-current">当前应用</span><h3>{{app.name}}</h3><p>{{app.description}}</p><span class="app-start">开始对话 <ArrowUpRight :size="16"/></span></button></div></section>
  <section v-if="section==='prompts'" class="studio-config"><div class="studio-section-head"><div><h3>本课程的助手配置</h3><p>配置仅属于你的账号与当前课程，保存后下一次提问生效。</p></div><button class="primary" :disabled="busy" @click="attempt(async()=>{await save();notice='配置已保存'})">保存配置</button></div><label>AI 应用<select v-model="config.app_id"><option v-for="app in apps" :value="app.id" :key="app.id">{{app.name}}</option></select></label><label>提示词模板<textarea v-model="config.template" rows="9" maxlength="12000" placeholder="例如：你是 {{course}} 的助教。请先给结论，再列出步骤。针对 {{question}}，补充一个自测问题。"></textarea></label><p class="studio-help">可用变量：<code v-text="'{{course}}'"></code> 课程名、<code v-text="'{{question}}'"></code> 本次问题。展开后的模板将进入模型的 system 消息。</p><label class="studio-check"><input v-model="config.use_knowledge" type="checkbox">默认检索课程知识库（最多 4 个相关片段）</label><h4>已添加的技能</h4><div class="studio-chips"><button v-for="s in skills.filter(s=>config.skill_ids.includes(s.id))" :key="s.id" @click="toggle(s)">{{s.icon}} {{s.name}} <X :size="12"/></button><span v-if="!config.skill_ids.length">到技能广场添加第一项技能</span></div></section>
  <section v-if="section==='mcp'">
    <div class="studio-section-head"><div><h3>让 AI 连接真实能力</h3><p>官方 MCP SDK 服务 · 浏览器 · 隔离脚本 · 课程工具</p></div><button v-if="manager&&!servers.some(s=>s.name==='campus-tools')" class="secondary" :disabled="busy" @click="addServer(true)"><Plus :size="15"/>添加本地工具服务</button></div>
    <div v-for="s in platformServers" :key="s.id" class="mcp-card"><div class="mcp-card-head"><span class="mcp-status" :class="{online:s.connected}"></span><div><h4>平台内置工具</h4><small>{{s.connected?'可用 · 所有课程成员均可按需绑定':'暂时不可用，请联系平台管理员'}}</small></div></div><div v-for="tool in s.tools" :key="tool.name" class="mcp-tool"><div><strong>{{tool.name}}</strong><p>{{tool.description}}</p></div><div class="mcp-tool-actions"><button class="skill-add" :class="{added:config.mcp_refs.includes(`${tool.name}@${s.name}`)}" :disabled="busy||!s.connected" @click="bindTool(s,tool.name)">{{config.mcp_refs.includes(`${tool.name}@${s.name}`)?'已绑定':'绑定到助手'}}</button><button class="skill-detail" @click="prepareTest(s,tool.name)">测试工具</button></div></div></div><p v-if="!manager" class="studio-help">平台工具可以直接绑定使用；个人外部 MCP 服务器由教师或管理员登记维护。</p>
    <template v-else><div class="mcp-register"><input v-model="serverName" placeholder="服务器名，例如 my-tools" aria-label="服务器名"><input v-model="serverUrl" placeholder="https://example.com/mcp" aria-label="MCP 地址"><input v-model="tokenEnv" placeholder="令牌环境变量，例如 MCP_MY_TOKEN" aria-label="令牌环境变量"><button class="primary" :disabled="busy" @click="addServer()">登记服务</button></div><p class="studio-help">密钥只在服务器环境变量中保存；外部主机需加入 MCP_ALLOWED_HOSTS。登记后连接以发现可用工具。</p>
    <div v-for="s in servers" :key="s.id" class="mcp-card"><div class="mcp-card-head"><span class="mcp-status" :class="{online:s.connected}"></span><div><h4>{{s.name}}</h4><small>{{s.url}} · {{s.has_token?'已配置令牌':'未配置令牌'}}</small></div><button class="secondary" :disabled="busy" @click="connect(s)">{{s.connected?'断开':'连接并发现工具'}}</button><button class="studio-icon" title="删除服务器" @click="attempt(async()=>{await api(`agent/mcp/${s.id}/`,'DELETE');await load()})"><Trash2 :size="16"/></button></div><p v-if="s.error" class="mcp-error">{{s.error}}</p><div v-for="tool in s.tools" :key="tool.name" class="mcp-tool"><div><strong>{{tool.name}}</strong><p>{{tool.description}}</p><details><summary>参数结构</summary><pre>{{JSON.stringify(tool.inputSchema,null,2)}}</pre></details></div><div class="mcp-tool-actions"><button class="skill-add" :class="{added:config.mcp_refs.includes(`${tool.name}@${s.name}`)}" :disabled="busy" @click="bindTool(s,tool.name)">{{config.mcp_refs.includes(`${tool.name}@${s.name}`)?'已绑定':'绑定到助手'}}</button><button class="skill-detail" @click="prepareTest(s,tool.name)">测试工具</button></div></div></div>
    </template><div v-if="testing" class="studio-config"><h4>真实工具测试 · {{testTool}}</h4><textarea v-model="testArgs" rows="5" aria-label="测试参数 JSON"></textarea><button class="primary" :disabled="busy" @click="tryTool"><Play :size="14"/>执行测试</button><pre v-if="testOutput">{{testOutput}}</pre></div>
  </section>
  <section v-if="section==='traces'"><div class="studio-section-head"><div><h3>每一次回答，都有迹可循</h3><p>查看当前对话每轮的请求参数、原始返回、技能与工具调用。</p></div><div class="trace-buttons"><button class="secondary" :disabled="busy" @click="loadTraces"><RefreshCw :size="14"/>刷新</button><button class="secondary" :disabled="!traces.length" @click="exportTrace"><Download :size="14"/>导出证据</button></div></div><div v-if="!traces.length" class="studio-empty">先在课程助手中发送一条消息，运行记录会出现在这里。</div><div v-else class="trace-layout"><div class="trace-list"><button v-for="t in traces" :key="t.id" :class="{active:selectedTrace?.id===t.id}" @click="selectedTrace=t"><strong>运行 #{{t.id}}</strong><small>{{t.model}} · {{t.status}}</small><small>{{new Date(t.started_at).toLocaleString('zh-CN')}}</small></button></div><div v-if="selectedTrace" class="trace-events"><div v-if="selectedTrace.error" class="mcp-error">{{selectedTrace.error}}</div><details v-for="event in selectedTrace.events" :key="event.sequence" :open="event.event_type==='context'" class="trace-event"><summary><span>{{eventLabel(event.event_type)}}</span><small>{{event.payload.round?`第 ${event.payload.round} 轮`:''}} {{event.payload.name||''}} {{event.payload.status||''}}</small></summary><pre>{{JSON.stringify(event.payload,null,2)}}</pre></details></div></div></section>
  <div v-if="detail" class="studio-modal-backdrop" @click.self="detail=null"><div class="studio-modal"><button class="modal-close" aria-label="关闭技能详情" @click="detail=null"><X :size="20"/></button><span class="studio-eyebrow">SKILL / {{detail.version}}</span><h2>{{detail.icon}} {{detail.name}}</h2><p>{{detail.description}}</p><div class="skill-provenance">{{detail.source}}<a v-if="detail.source_url" :href="detail.source_url" target="_blank" rel="noopener">查看固定版本来源 ↗</a><span v-if="detail.license">{{detail.license}}</span></div><p v-if="detail.requirements" class="studio-help">{{detail.requirements}}</p><button class="primary" :disabled="busy" @click="toggle(detail)">{{config.skill_ids.includes(detail.id)?'从本课程助手移除':'添加到本课程助手'}}</button><h4>技能指令</h4><div class="markdown-body skill-instructions" v-html="renderMarkdown(detail.instructions||'')"></div><h4>参考文件与脚本</h4><details v-for="(body,path) in detail.resources" :key="path"><summary><FileCode2 :size="14"/> {{path}}</summary><pre>{{body}}</pre></details><p v-if="!Object.keys(detail.resources||{}).length" class="studio-help">此技能无附加文件。</p></div></div>
</div>
</template>

<style scoped>
